import{_ as s,a0 as r,w as l,s as a,ao as u,I as p,x as t,a1 as i,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"如何在 Linux 下執行 bin 文件 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 下執行 bin 文件 | LCTT (201403) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 下執行 bin 文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 下執行 bin 文件 | LCTT (201403) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201403/How To Execute bin Files In Linux","title":"如何在 Linux 下執行 bin 文件","tag":"201403","desc":""},"relativePath":"201403/How To Execute bin Files In Linux.md","filePath":"[post].md"}'),x={name:"201403/How To Execute bin Files In Linux.md"};function d(m,n,g,b,T,f){const e=r("Link");return l(),a("div",null,[n[11]||(n[11]=u(`<h1 id="如何在-linux-下執行-bin-文件" tabindex="-1">如何在 Linux 下執行 bin 文件 <a class="header-anchor" href="#如何在-linux-下執行-bin-文件" aria-label="Permalink to “如何在 Linux 下執行 bin 文件”">​</a></h1><p>嗨，各位 <strong>Linux</strong> 極客們，</p><p>在這篇簡短教程中，我會指導你們如何在你的 Linux 機器上安裝 <strong>.bin</strong> 文件。並不是一些可怕的終端命令，我保證！但是我同樣會展示如何在終端上操作 。</p><p>###什麼是 .bin 文件？</p><p>.bin 文件是在 Linux 和類 Unix 操作系統上的自執行文件。在執行 .bin 文件之前，你需要給它執行權限。這可以通過命令列或者 gui 完成。如果你喜歡用命令列那麼打開一個新的終端並運行如下的命令來給予文件執行權限。</p><pre><code>chmod +x filename.bin
</code></pre><p>接着用下面的命令執行。</p><pre><code>./filename.bin
</code></pre><p>確保你在運行上面的命令的時候是超級用户。</p><p>那又如何從 gui 來完成呢？進入 .bin 文件的目錄並點擊鼠標右鍵，接着如下圖所示進入屬性。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/02/exec1.png" alt=""></p><p>選擇 <strong>Permissions</strong> 並勾選 <strong>Allow executing file as a program</strong> 。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/02/exec2.png" alt=""></p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/02/exec3.png" alt=""></p><p>雙擊文件後它就會執行。這樣就完成了。</p><hr>`,16)),p("p",null,[n[1]||(n[1]=t("via: ",-1)),i(e,{href:"http://www.unixmen.com/execute-bin-files-linux/"},{default:o(()=>[...n[0]||(n[0]=[t("http://www.unixmen.com/execute-bin-files-linux/",-1)])]),_:1})]),p("p",null,[n[4]||(n[4]=t("譯者：",-1)),i(e,{href:"https://github.com/geekpi"},{default:o(()=>[...n[2]||(n[2]=[t("geekpi",-1)])]),_:1}),n[5]||(n[5]=t(" 校對：",-1)),i(e,{href:"https://github.com/carolinewuyan"},{default:o(()=>[...n[3]||(n[3]=[t("Caroline",-1)])]),_:1})]),p("p",null,[n[8]||(n[8]=t("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...n[6]||(n[6]=[t("LCTT",-1)])]),_:1}),n[9]||(n[9]=t(" 原創翻譯，",-1)),i(e,{href:"http://linux.cn/"},{default:o(()=>[...n[7]||(n[7]=[t("Linux中國",-1)])]),_:1}),n[10]||(n[10]=t(" 榮譽推出",-1))])])}const c=s(x,[["render",d]]);export{C as __pageData,c as default};
